#!/usr/bin/env python3

from __future__ import annotations

import json
import os
from pathlib import Path
import socket
import sys


def read_json(path: str | Path, default):
    candidate = Path(path)
    if not candidate.exists():
        return default
    try:
        return json.loads(candidate.read_text(encoding="utf-8"))
    except Exception:
        return default


def write_json(path: str | Path, payload) -> None:
    candidate = Path(path)
    candidate.parent.mkdir(parents=True, exist_ok=True)
    candidate.write_text(json.dumps(payload, indent=2), encoding="utf-8")


def write_jsonl(path: str | Path, payload) -> None:
    candidate = Path(path)
    candidate.parent.mkdir(parents=True, exist_ok=True)
    with candidate.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(payload, sort_keys=True) + "\n")


def ensure_dir(path: str | Path) -> None:
    Path(path).mkdir(parents=True, exist_ok=True)


def socket_request(socket_path: str | Path, action: str, payload: dict | None = None) -> dict:
    client = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    try:
        client.connect(str(socket_path))
        client.sendall(
            json.dumps({"action": action, "payload": payload or {}}).encode("utf-8") + b"\n"
        )
        client.shutdown(socket.SHUT_WR)
        response = b""
        while True:
            chunk = client.recv(65536)
            if not chunk:
                break
            response += chunk
    finally:
        client.close()
    if not response:
        return {"exit_code": 1, "lines": ["Service returned no response."]}
    return json.loads(response.decode("utf-8"))


def run_client(socket_path: str | Path, action: str, payload: dict | None = None) -> int:
    response = socket_request(socket_path, action, payload)
    for line in response.get("lines", []):
        print(line)
    return int(response.get("exit_code", 0) or 0)


def serve(socket_path: str | Path, handler) -> None:
    socket_file = Path(socket_path)
    socket_file.parent.mkdir(parents=True, exist_ok=True)
    if socket_file.exists():
        socket_file.unlink()
    server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    server.bind(str(socket_file))
    os.chmod(socket_file, 0o777)
    server.listen(8)
    try:
        while True:
            conn, _addr = server.accept()
            with conn:
                request = b""
                while True:
                    chunk = conn.recv(65536)
                    if not chunk:
                        break
                    request += chunk
                if not request:
                    response = {"exit_code": 1, "lines": ["Empty request received."]}
                else:
                    try:
                        data = json.loads(request.decode("utf-8"))
                        response = handler(data.get("action"), data.get("payload") or {})
                    except Exception as exc:  # pragma: no cover - runtime safety
                        response = {"exit_code": 1, "lines": [f"Service error: {exc}"]}
                conn.sendall(json.dumps(response).encode("utf-8"))
    finally:
        server.close()
        if socket_file.exists():
            socket_file.unlink()


def receipt_entry(action: str, status: str, effect: dict | None = None) -> dict:
    return {
        "action": action,
        "status": status,
        "authoritative_effect": effect or {},
    }


def fail(lines: list[str], exit_code: int = 1) -> dict:
    return {"exit_code": exit_code, "lines": lines}


def ok(lines: list[str], effect: dict | None = None) -> dict:
    response = {"exit_code": 0, "lines": lines}
    if effect is not None:
        response["effect"] = effect
    return response


def require_args(argv: list[str], count: int, usage: str) -> list[str]:
    if len(argv) != count:
        print(usage)
        raise SystemExit(1)
    return argv[1:]


def maybe_help(argv: list[str], description: str, usage: str) -> None:
    if any(arg in ("-h", "--help") for arg in argv[1:]):
        print(description)
        print(usage)
        raise SystemExit(0)

